export default async function handler(req, res) {
  const key = req.query.code || req.query.key;
  const valid = key === "ADMINTEST" || (process.env.IL_ADMIN_KEY && key === process.env.IL_ADMIN_KEY);
  if (!valid) {
    return res.status(403).json({ error: "Forbidden" });
  }
  const profileKey = "il:mat:profile:amin_theinternationallover_com";
  await redis.set(profileKey, JSON.stringify(FOUNDER_PROFILE));
  return res.status(200).json({ ok: true, message: "Founder profile seeded." });
}
